"use client";

import { cn } from "@/lib/utils";
import { X } from "lucide-react";
import React, { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { createPortal } from "react-dom";
import { DialogContext, useDialog } from "./dialog-context";

// ==========================================
// 2. ROOT COMPONENT
// ==========================================
export interface DialogProps {
  children: React.ReactNode;
  open?: boolean;
  defaultOpen?: boolean;
  onOpenChange?: (open: boolean) => void;
}

export function Dialog({
  children,
  open: controlledOpen,
  defaultOpen = false,
  onOpenChange,
}: DialogProps) {
  const isControlled = controlledOpen !== undefined;
  const [uncontrolledOpen, setUncontrolledOpen] = useState(defaultOpen);
  const open = isControlled ? controlledOpen : uncontrolledOpen;

  // What `setOpen` reads when it fires, refreshed after every commit so the
  // setter itself never has to be rebuilt. Identity matters here: DialogContent
  // registers on the open-dialog stack in an effect keyed by this function, and
  // a setter that changed on every render would re-register a dialog that is
  // merely re-rendering — handing an outer dialog the topmost slot while a
  // nested one is still on screen, so Escape would dismiss the wrong window.
  const latest = useRef({ open, isControlled, onOpenChange });
  useEffect(() => {
    latest.current = { open, isControlled, onOpenChange };
  });

  const setOpen = useCallback(
    (newOpen: boolean | ((prev: boolean) => boolean)) => {
      const current = latest.current;
      const nextState =
        typeof newOpen === "function" ? newOpen(current.open) : newOpen;
      if (!current.isControlled) setUncontrolledOpen(nextState);
      current.onOpenChange?.(nextState);
    },
    [],
  );

  const value = useMemo(() => ({ open, setOpen }), [open, setOpen]);

  return (
    <DialogContext.Provider value={value}>{children}</DialogContext.Provider>
  );
}

// ==========================================
// 3. TRIGGER
// ==========================================
export interface DialogTriggerProps
  extends React.HTMLAttributes<HTMLDivElement> {
  asChild?: boolean; // Note: For a real asChild implementation, you'd use Radix Slot. Here we use a generic wrapper.
}

export function DialogTrigger({
  children,
  className,
  ...props
}: DialogTriggerProps) {
  const { setOpen } = useDialog();

  return (
    <div
      role="button"
      tabIndex={0}
      onClick={() => setOpen(true)}
      onKeyDown={(e) => {
        if (e.key === "Enter" || e.key === " ") {
          e.preventDefault();
          setOpen(true);
        }
      }}
      className={cn("inline-block", className)}
      {...props}
    >
      {children}
    </div>
  );
}

// ==========================================
// 3b. CLOSE BUTTON
// ==========================================
export type DialogCloseProps = React.ButtonHTMLAttributes<HTMLButtonElement>;

export function DialogClose({
  children,
  className,
  onClick,
  ...props
}: DialogCloseProps) {
  const { setOpen } = useDialog();

  return (
    <button
      type="button"
      onClick={(e) => {
        onClick?.(e);
        setOpen(false);
      }}
      className={className}
      {...props}
    >
      {children}
    </button>
  );
}

// ==========================================
// 4. CONTENT (Portal Renderer with Scroll Lock)
// ==========================================

/**
 * The panel width scale, from a compact confirm up to a full-page surface.
 *
 * `full` also drops the rounding, border and viewport-height cap that the
 * inset sizes rely on, so the panel really does fill the screen rather than
 * sitting as a very wide card inside it. Its rows are centred in that screen
 * (`content-center` overrides the panel's `content-start`) and kept to the
 * `md` column width, so the content reads as a dialog floating in the middle
 * of the page rather than a strip pinned to the top-left. Pass `className`
 * (it merges after the size) to lay the surface out edge to edge instead.
 */
const DIALOG_SIZES = {
  sm: "max-w-sm",
  md: "max-w-lg",
  lg: "max-w-2xl",
  xl: "max-w-4xl",
  full: "max-w-none h-full max-h-none rounded-none border-0 content-center justify-center grid-cols-[minmax(0,32rem)]",
} as const;

export type DialogSize = keyof typeof DIALOG_SIZES;

/**
 * Every dialog currently on screen, outermost first.
 *
 * Escape is listened for on the document, so a dialog opened from inside
 * another one would otherwise dismiss both on a single press — each open
 * content has its own live listener. Only the entry on top of this stack
 * reacts, and its position also decides which panel paints above the rest.
 */
const openDialogs: symbol[] = [];

export interface DialogContentProps
  extends React.HTMLAttributes<HTMLDivElement> {
  hideCloseButton?: boolean;
  /** Panel width — `full` fills the viewport edge to edge. Defaults to `md`. */
  size?: DialogSize;
}

export function DialogContent({
  className,
  children,
  hideCloseButton = false,
  size = "md",
  ...props
}: DialogContentProps) {
  const { open, setOpen } = useDialog();
  const contentRef = useRef<HTMLDivElement>(null);
  const [portalTarget, setPortalTarget] = useState<HTMLElement | null>(null);
  // Identity for this dialog on the stack above. A symbol rather than a count
  // so a dialog can be removed by value, wherever it sits when it closes.
  const idRef = useRef<symbol | null>(null);
  if (idRef.current === null) idRef.current = Symbol("dialog");
  const [depth, setDepth] = useState(0);

  // Resolves the document this dialog actually lives in, which is not always
  // the global one — previews portal components into an iframe. Resolving in a
  // callback ref rather than reading a ref during render keeps render pure, and
  // a null target doubles as the "not mounted yet" signal that guards SSR.
  const setAnchor = useCallback((node: HTMLSpanElement | null) => {
    setPortalTarget(node ? node.ownerDocument.body : null);
  }, []);

  // Handle Escape Key & Body Scroll Lock
  useEffect(() => {
    if (!open) return;

    // Resolve the document/window the dialog actually lives in (supports iframe rendering).
    const doc = contentRef.current?.ownerDocument ?? document;
    const win = doc.defaultView ?? window;

    // Claim a slot on the stack. Whatever opens last is what the user is
    // looking at, so it takes both the Escape key and the highest layer.
    const id = idRef.current as symbol;
    openDialogs.push(id);
    // Depth comes from a module-level stack of open dialogs, which only exists once this one has mounted and claimed a slot.
    setDepth(openDialogs.length - 1);

    // Lock body scroll. A nested dialog reads the lock the outer one already
    // applied as its "original", so unwinding in either order is safe.
    const originalStyle = win.getComputedStyle(doc.body).overflow;
    doc.body.style.overflow = "hidden";

    // Escape listener — ignored unless this is the topmost dialog.
    const handleEscape = (e: KeyboardEvent) => {
      if (e.key !== "Escape") return;
      if (openDialogs[openDialogs.length - 1] !== id) return;
      setOpen(false);
    };
    doc.addEventListener("keydown", handleEscape);

    return () => {
      const index = openDialogs.indexOf(id);
      if (index !== -1) openDialogs.splice(index, 1);
      doc.body.style.overflow = originalStyle;
      doc.removeEventListener("keydown", handleEscape);
    };
  }, [open, setOpen, portalTarget]);

  if (!portalTarget || !open) return <span ref={setAnchor} hidden />;

  return (
    <>
      <span ref={setAnchor} hidden />
      {createPortal(
    <div
      className={cn(
        "fixed inset-0 z-50 flex items-center justify-center",
        // A full-page panel has no room for the inset gutter the others sit in.
        size === "full" ? "p-0" : "p-4 sm:p-6",
      )}
      // Stack position, not a fixed layer: a dialog opened from inside another
      // one has to paint above its parent's backdrop.
      style={{ zIndex: 50 + depth * 10 }}
    >
      {/* Backdrop */}
      <div
        className="fixed inset-0 bg-black/30 dark:bg-black/80 backdrop-blur-sm animate-in fade-in duration-200"
        onClick={() => setOpen(false)}
        aria-hidden="true"
      />

      {/* Dialog Window */}
      <div
        ref={contentRef}
        role="dialog"
        aria-modal="true"
        className={cn(
          // `content-start` is what keeps the rows at their natural height.
          // The panel is a grid, so the moment it has a determinate height —
          // `size="full"`, or a height passed through className — the default
          // `align-content: stretch` inflates every auto row to fill it, and a
          // footer button stretches along with the row holding it.
          "relative z-50 w-full grid content-start gap-4 border border-border bg-card text-card-foreground p-6 shadow-lg rounded-xl max-h-[85vh] overflow-y-auto",
          DIALOG_SIZES[size],
          "animate-in fade-in zoom-in-95 slide-in-from-top-[5%] duration-200",
          className,
        )}
        {...props}
      >
        {children}

        {!hideCloseButton && (
          <button
            onClick={() => setOpen(false)}
            className="absolute right-4 top-4 rounded-sm opacity-70 ring-offset-card transition-opacity hover:opacity-100 focus:outline-none focus:ring-2 focus:ring-ring focus:ring-offset-2 disabled:pointer-events-none data-[state=open]:bg-muted data-[state=open]:text-muted-foreground"
          >
            <X className="h-4 w-4" />
            <span className="sr-only">Close</span>
          </button>
        )}
      </div>
    </div>,
    portalTarget,
      )}
    </>
  );
}

// ==========================================
// 5. LAYOUT SUB-COMPONENTS
// ==========================================
export function DialogHeader({
  className,
  ...props
}: React.HTMLAttributes<HTMLDivElement>) {
  return (
    <div
      className={cn(
        "flex flex-col space-y-1.5 text-center sm:text-left",
        className,
      )}
      {...props}
    />
  );
}

export function DialogFooter({
  className,
  ...props
}: React.HTMLAttributes<HTMLDivElement>) {
  return (
    <div
      className={cn(
        "flex flex-col-reverse sm:flex-row sm:justify-end sm:space-x-2 mt-2",
        className,
      )}
      {...props}
    />
  );
}

export function DialogTitle({
  className,
  ...props
}: React.HTMLAttributes<HTMLHeadingElement>) {
  return (
    <h2
      className={cn(
        "text-lg font-semibold leading-none tracking-tight",
        className,
      )}
      {...props}
    />
  );
}

export function DialogDescription({
  className,
  ...props
}: React.HTMLAttributes<HTMLParagraphElement>) {
  return (
    <p
      className={cn("text-sm text-muted-foreground", className)}
      {...props}
    />
  );
}

"use client";

import React, { createContext, useContext } from "react";

const COLOR_HEX_MAP: Record<string, string> = {
  indigo: "#6366f1",
  rose: "#f43f5e",
  emerald: "#10b981",
  zinc: "#71717a",
  amber: "#f59e0b",
  blue: "#3b82f6",
};

export const getThemeStyles = (color?: string) => {
  if (!color || color === "default" || color === "primary") {
    return { style: {} };
  }

  const resolvedColor =
    COLOR_HEX_MAP[color] || (color.startsWith("#") ? color : undefined);

  if (resolvedColor) {
    return {
      style: {
        "--primary": resolvedColor,
      } as React.CSSProperties,
    };
  }

  return { style: {} };
};

interface DialogContextType {
  open: boolean;
  setOpen: React.Dispatch<React.SetStateAction<boolean>>;
  color?: string;
  style?: React.CSSProperties;
}

export const DialogContext = createContext<DialogContextType | undefined>(undefined);

export function useDialog() {
  const context = useContext(DialogContext);
  if (!context)
    throw new Error("Dialog components must be used within a <Dialog> root.");
  return context;
}

"use client";

import { cn } from "@/lib/utils";
import { Check, Copy, X } from "lucide-react";
import React, { forwardRef, useCallback, useEffect, useRef, useState } from "react";

// ==========================================
// THEME
// ==========================================
export type CopyButtonColor = "primary" | "indigo" | "rose" | "emerald" | "zinc" | string;
export type CopyButtonVariant = "solid" | "outline" | "ghost" | "soft";
export type CopyButtonSize = "sm" | "md" | "lg";

const colorThemes: Record<string, Record<string, string>> = {
  primary: {
    solid: "bg-primary text-primary-foreground hover:bg-primary/90",
    soft: "bg-primary/10 text-primary hover:bg-primary/15",
    text: "text-primary",
    ring: "focus-visible:ring-primary/30",
  },
  indigo: {
    solid: "bg-indigo-600 text-white hover:bg-indigo-700",
    soft: "bg-indigo-500/10 text-indigo-600 dark:text-indigo-400 hover:bg-indigo-500/15",
    text: "text-indigo-600 dark:text-indigo-400",
    ring: "focus-visible:ring-indigo-500/30",
  },
  rose: {
    solid: "bg-rose-600 text-white hover:bg-rose-700",
    soft: "bg-rose-500/10 text-rose-600 dark:text-rose-400 hover:bg-rose-500/15",
    text: "text-rose-600 dark:text-rose-400",
    ring: "focus-visible:ring-rose-500/30",
  },
  emerald: {
    solid: "bg-emerald-600 text-white hover:bg-emerald-700",
    soft: "bg-emerald-500/10 text-emerald-600 dark:text-emerald-400 hover:bg-emerald-500/15",
    text: "text-emerald-600 dark:text-emerald-400",
    ring: "focus-visible:ring-emerald-500/30",
  },
  zinc: {
    solid: "bg-zinc-900 text-white hover:bg-zinc-800 dark:bg-white dark:text-zinc-900 dark:hover:bg-zinc-200",
    soft: "bg-zinc-500/10 text-zinc-900 dark:text-zinc-100 hover:bg-zinc-500/15",
    text: "text-zinc-900 dark:text-zinc-100",
    ring: "focus-visible:ring-zinc-500/30",
  },
};

const getTheme = (color: string) => {
  if (color.startsWith("#")) {
    return {
      theme: {
        solid: "bg-[var(--copy-color)] text-white hover:opacity-90",
        soft: "bg-[color-mix(in_oklab,var(--copy-color)_12%,transparent)] text-[var(--copy-color)] hover:bg-[color-mix(in_oklab,var(--copy-color)_18%,transparent)]",
        text: "text-[var(--copy-color)]",
        ring: "focus-visible:ring-[color-mix(in_oklab,var(--copy-color)_30%,transparent)]",
      },
      style: { "--copy-color": color } as React.CSSProperties,
    };
  }
  return { theme: colorThemes[color] ?? colorThemes.primary, style: {} };
};

// Keyframes ship inline so the block stays self-contained — no plugin, no
// globals.css entry. Names are prefixed to avoid clashing with app styles.
const KEYFRAMES = `
@keyframes copy-btn-pop {
  0% { transform: scale(0.4) rotate(-20deg); opacity: 0; }
  60% { transform: scale(1.2) rotate(4deg); opacity: 1; }
  100% { transform: scale(1) rotate(0); opacity: 1; }
}
@keyframes copy-btn-rise {
  from { transform: translateY(0.45em); opacity: 0; }
  to { transform: translateY(0); opacity: 1; }
}`;

// ==========================================
// HOOK
// ==========================================
export type CopyStatus = "idle" | "copied" | "error";

/**
 * Copies text to the clipboard and reports a status that resets itself after
 * `timeout` ms. Falls back to a hidden textarea + execCommand where the async
 * Clipboard API is unavailable (older browsers, non-secure origins).
 */
export function useCopyToClipboard(timeout = 2000) {
  const [status, setStatus] = useState<CopyStatus>("idle");
  const timer = useRef<ReturnType<typeof setTimeout> | null>(null);

  useEffect(
    () => () => {
      if (timer.current) clearTimeout(timer.current);
    },
    [],
  );

  const copy = useCallback(
    async (text: string) => {
      let ok = false;
      try {
        if (typeof navigator !== "undefined" && navigator.clipboard?.writeText) {
          await navigator.clipboard.writeText(text);
          ok = true;
        }
      } catch {
        ok = false;
      }
      if (!ok && typeof document !== "undefined") {
        const ta = document.createElement("textarea");
        ta.value = text;
        ta.setAttribute("readonly", "");
        ta.style.position = "fixed";
        ta.style.opacity = "0";
        document.body.appendChild(ta);
        ta.select();
        try {
          ok = document.execCommand("copy");
        } catch {
          ok = false;
        }
        document.body.removeChild(ta);
      }
      setStatus(ok ? "copied" : "error");
      if (timer.current) clearTimeout(timer.current);
      timer.current = setTimeout(() => setStatus("idle"), timeout);
      return ok;
    },
    [timeout],
  );

  return { copy, status, copied: status === "copied" };
}

// ==========================================
// COPY BUTTON
// ==========================================
export interface CopyButtonProps
  extends Omit<React.ButtonHTMLAttributes<HTMLButtonElement>, "value" | "onCopy" | "color"> {
  /** The text that lands on the clipboard. */
  value: string;
  /** Resting label. Omit for an icon-only button. Default "Copy". */
  label?: React.ReactNode;
  /** Label shown after a successful copy. Default "Copied!". */
  copiedLabel?: React.ReactNode;
  /** Label shown when the clipboard write fails. Default "Failed". */
  errorLabel?: React.ReactNode;
  /** Hide the label entirely and render a square icon button. */
  iconOnly?: boolean;
  /** How long the copied state lingers, in ms. Default 2000. */
  timeout?: number;
  variant?: CopyButtonVariant;
  size?: CopyButtonSize;
  /** Theme colour — a preset name or any hex code. */
  color?: CopyButtonColor;
  /** Fires after the clipboard write with the value and whether it succeeded. */
  onCopy?: (value: string, ok: boolean) => void;
}

export const CopyButton = forwardRef<HTMLButtonElement, CopyButtonProps>(
  (
    {
      value,
      label = "Copy",
      copiedLabel = "Copied!",
      errorLabel = "Failed",
      iconOnly = false,
      timeout = 2000,
      variant = "solid",
      size = "md",
      color = "primary",
      onCopy,
      className,
      style,
      onClick,
      disabled,
      ...props
    },
    ref,
  ) => {
    const { copy, status } = useCopyToClipboard(timeout);
    const { theme, style: themeStyle } = getTheme(color);
    // No entrance animation on first paint — the pop is for state changes only.
    const interacted = useRef(false);

    const sizes = {
      sm: { btn: "h-8 text-xs gap-1.5 rounded-md", pad: "px-2.5", square: "w-8", icon: "w-3.5 h-3.5" },
      md: { btn: "h-10 text-sm gap-2 rounded-md", pad: "px-4", square: "w-10", icon: "w-4 h-4" },
      lg: { btn: "h-12 text-base gap-2 rounded-lg", pad: "px-5", square: "w-12", icon: "w-5 h-5" },
    }[size];

    const variants = {
      solid: theme.solid,
      soft: theme.soft,
      outline: cn(
        "border border-border bg-background text-foreground hover:bg-muted",
      ),
      ghost: "bg-transparent text-foreground hover:bg-muted",
    };

    const isCopied = status === "copied";
    const isError = status === "error";
    const currentLabel = isCopied ? copiedLabel : isError ? errorLabel : label;
    const Icon = isCopied ? Check : isError ? X : Copy;

    return (
      <>
      {/* Keyframes live beside the button, not inside it, so the live region
          and textContent stay clean. */}
      <style>{KEYFRAMES}</style>
      <button
        ref={ref}
        type="button"
        disabled={disabled}
        aria-live="polite"
        aria-label={iconOnly ? (isCopied ? "Copied" : "Copy to clipboard") : undefined}
        data-state={status}
        onClick={(e) => {
          onClick?.(e);
          if (e.defaultPrevented) return;
          interacted.current = true;
          void copy(value).then((ok) => onCopy?.(value, ok));
        }}
        className={cn(
          "relative inline-flex shrink-0 items-center justify-center font-semibold whitespace-nowrap select-none transition-all duration-200 active:scale-95 outline-none focus-visible:ring-4 disabled:opacity-50 disabled:pointer-events-none",
          sizes.btn,
          iconOnly ? sizes.square : sizes.pad,
          variants[variant],
          theme.ring,
          // Success flashes the accent, whatever the resting variant is.
          isCopied && variant !== "solid" && cn(theme.text),
          isError && "text-red-600 dark:text-red-400",
          className,
        )}
        style={{ ...themeStyle, ...style }}
        {...props}
      >
        {/* Swapping the element (via key) restarts the pop each time. */}
        <Icon
          key={status}
          className={cn(sizes.icon, "shrink-0")}
          style={interacted.current ? { animation: "copy-btn-pop 0.35s cubic-bezier(0.34,1.56,0.64,1) both" } : undefined}
          strokeWidth={isCopied ? 3 : 2}
        />
        {!iconOnly && (
          <span
            key={`label-${status}`}
            className="inline-block"
            style={interacted.current ? { animation: "copy-btn-rise 0.25s ease-out both" } : undefined}
          >
            {currentLabel}
          </span>
        )}
      </button>
      </>
    );
  },
);
CopyButton.displayName = "CopyButton";

// ==========================================
// COPY FIELD (read-only input + button)
// ==========================================
export interface CopyFieldProps
  extends Omit<React.HTMLAttributes<HTMLDivElement>, "color" | "prefix"> {
  /** The text shown in the field and copied by the button. */
  value: string;
  label?: string;
  /** Props forwarded to the embedded button (label, variant, colour…). */
  buttonProps?: Omit<CopyButtonProps, "value">;
  size?: CopyButtonSize;
  color?: CopyButtonColor;
  /** Render the button inside the field's right edge instead of beside it. */
  inset?: boolean;
  /** Select the whole value when the field is clicked. Default true. */
  selectOnClick?: boolean;
  /** Left-side adornment inside the field, e.g. a link icon. */
  prefix?: React.ReactNode;
}

export const CopyField = forwardRef<HTMLDivElement, CopyFieldProps>(
  (
    {
      value,
      label,
      buttonProps,
      size = "md",
      color = "primary",
      inset = false,
      selectOnClick = true,
      prefix,
      className,
      ...props
    },
    ref,
  ) => {
    const heights = { sm: "h-8 text-xs", md: "h-10 text-sm", lg: "h-12 text-base" }[size];
    const { theme, style } = getTheme(color);

    return (
      <div ref={ref} className={cn("flex w-full flex-col gap-1.5", className)} {...props}>
        {label && <span className="text-sm font-semibold text-foreground">{label}</span>}
        <div className={cn("flex w-full items-center", inset ? "relative" : "gap-2")}>
          {prefix && !inset && (
            <span className="shrink-0 text-muted-foreground">{prefix}</span>
          )}
          <input
            readOnly
            value={value}
            onClick={selectOnClick ? (e) => e.currentTarget.select() : undefined}
            className={cn(
              "w-full min-w-0 rounded-md border border-border bg-background px-3 font-mono text-foreground outline-none transition-shadow focus-visible:ring-4",
              theme.ring,
              heights,
              inset && (size === "sm" ? "pr-10" : size === "lg" ? "pr-14" : "pr-12"),
              prefix && inset && "pl-9",
            )}
            style={style}
          />
          {prefix && inset && (
            <span className="pointer-events-none absolute left-3 text-muted-foreground [&>svg]:w-4 [&>svg]:h-4">
              {prefix}
            </span>
          )}
          <CopyButton
            value={value}
            size={size}
            color={color}
            {...(inset
              ? {
                  iconOnly: true,
                  variant: "ghost" as const,
                  className: cn("absolute right-1", size === "sm" ? "h-6 w-6" : size === "lg" ? "h-10 w-10" : "h-8 w-8"),
                }
              : {})}
            {...buttonProps}
          />
        </div>
      </div>
    );
  },
);
CopyField.displayName = "CopyField";
